mapper.insert:
INSERT INTO transfer_history (
    trace_id, from_account_no, to_account_no, amount, fee, currency, status, memo, created_at, created_by
) VALUES (
    #{traceId}, #{fromAccountNo}, #{toAccountNo}, #{amount}, #{fee}, #{currency},
    #{status}, #{memo}, now(), #{createdBy}
)

mapper.select:
SELECT transfer_id, trace_id, from_account_no, to_account_no, amount, fee,
       currency, status, memo, created_at, created_by
  FROM transfer_history
 WHERE from_account_no = #{accountNo}
    OR to_account_no = #{accountNo}
 ORDER BY created_at DESC, transfer_id DESC
 LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM transfer_history
 WHERE from_account_no = #{accountNo}
    OR to_account_no = #{accountNo}
